-- Pulmocare: initial database installation, generated by npm run db:bundle.
-- Target project: dnxwecpzjobtnclyywkz. Run as postgres in Supabase SQL Editor.
-- All-or-nothing transaction. Existing Pulmocare objects cause a safe failure.
-- No DROP, no patient records, no credentials and no automatic administrative role grant.
BEGIN;
SELECT pg_advisory_xact_lock(11092026);
DO $preflight$
BEGIN
  IF to_regclass('public.profiles') IS NOT NULL
    OR to_regclass('public.service_requests') IS NOT NULL
    OR EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'private')
    OR EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pulmocare_executor') THEN
    RAISE EXCEPTION 'Existing application objects: inspect database before migrating';
  END IF;
  IF to_regclass('auth.users') IS NULL OR to_regclass('storage.buckets') IS NULL THEN
    RAISE EXCEPTION 'This installation requires Supabase Auth and Storage';
  END IF;
END;
$preflight$;
CREATE SCHEMA IF NOT EXISTS supabase_migrations;
CREATE TABLE IF NOT EXISTS supabase_migrations.schema_migrations (
  version text PRIMARY KEY, statements text[], name text
);
REVOKE ALL ON SCHEMA supabase_migrations FROM PUBLIC, anon, authenticated;
REVOKE ALL ON supabase_migrations.schema_migrations FROM PUBLIC, anon, authenticated;
-- 20260911000001_foundation.sql
-- SHA256 7c078e14511093c0c12d436fac308db5185afffbeb0cabec2b183f029fc0566d
-- Auth and Storage are managed by Supabase; never recreate them in migrations.
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
CREATE SCHEMA private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated, service_role;
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT USAGE ON SCHEMA private TO authenticated;

-- No login, membership or bypass-RLS: owns only tightly scoped RPC functions.
CREATE ROLE pulmocare_executor NOLOGIN NOINHERIT NOBYPASSRLS;
GRANT USAGE ON SCHEMA public, private, auth TO pulmocare_executor;
GRANT EXECUTE ON FUNCTION auth.uid() TO pulmocare_executor;

CREATE FUNCTION private.stamp() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.id := OLD.id;
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
  END IF;
  NEW.updated_at := statement_timestamp();
  NEW.updated_by := (
    SELECT id FROM public.profiles WHERE auth_user_id = auth.uid() AND active
  );
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := statement_timestamp();
    NEW.created_by := NEW.updated_by;
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION private.stamp() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.stamp() TO pulmocare_executor;

CREATE FUNCTION private.immutable() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  RAISE EXCEPTION 'Record is immutable' USING ERRCODE = '23514';
END;
$$;
REVOKE ALL ON FUNCTION private.immutable() FROM PUBLIC;

