   AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id=d.bucket_id AND o.name=d.object_path)) <> 2 THEN
  RAISE EXCEPTION 'Upload degree and professional license before approval' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$$;
